head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.visuShrsLabelNm = "주식";
scwin.strCbd_NPARVALSTK_YN = "N^아니오,Y^예";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vSecugrpID, scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;
scwin.gPrtdepoSeq;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let parentWin = $c.frame.path("../");
        const vCoBzProcsNo = parentWin.scwin.vBzProcsNo;
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vSecugrpID = parentWin.cmb_SECUGRP_ID.getValue();
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = parentWin.cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue();
        txb_ISUR_CD.setValue(parentWin.txb_ISUR_CD.getValue());
        txb_COM_NM.setValue(parentWin.txb_COM_NM.getValue());
        rowPos = parentWin.dts_Isu.getFocusedRowIndex();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        // resizeToWin() ;
        await scwin.searchCode();
        await scwin.setComboCode();
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        scwin.setInitLabel();
        scwin.setSumblComponent();
        scwin.setPanelPREFSTK(false); // 일단 false;
        scwin.setPREFSTKItem(false); // 일단 false;

        if (scwin.vBzProcsNo !== "") {
            await scwin.readSync();
            // 보호예수읽어온다
            await scwin.prtdepoReadSync();
        } else {
            const sbmOptions = {
                id : "sbm_dts_Isu",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Isu=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Isu.insertRow();
            if (vCoBzProcsNo === "") {
                await $c.win.alert("먼저 회사정보를 입력후 종목정보를 입력바랍니다.");
                buttonSet.setErrorStatus(); // disable 시킨다.

            } else {
                edt_LIST_DD.setValue(parentWin.edt_LIST_DD.getValue());
                const vlistClssCd = parentWin.cmb_LIST_CLSS_CD.getValue();
                let vListMethdTpCd;
                const vListMethdTpUpCd = vlistClssCd.substring(0, 1);
                if (vListMethdTpUpCd === '1') {
                    vListMethdTpCd = LIST_METHD_TP_CD_4;
                } else if (vListMethdTpUpCd === '2') {
                    vListMethdTpCd = LIST_METHD_TP_CD_5;
                }
                cmb_LIST_METHD_TP_CD.setValue(vListMethdTpCd);
            }
            let vCurDate = $c.ut.cGetToday("yyyymmdd");
            if (edt_LIST_DD.getValue() <= vCurDate) {
                buttonSet.setErrorStatus(); // disable 시킨다.

            }
            if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
                // 자동 settiong
                panel_ISU_ENG_SYMBL.show("");
                txb_ISU_ENG_SYMBL.setValue(parentWin.txb_ISUR_SYMBL.getValue());
            } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD === '6') {
                panel_ISU_ENG_SYMBL.hide();
            }

            // 보호예수초기화
            await scwin.prtdepoReadSyncSetHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

