 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edt_PARVAL_OnKillFocus = async function() {
    try {
        if (cmb_NPARVALSTK_YN.getValue() === 'N' || cmb_NPARVALSTK_YN.getValue() === '') {
            await scwin.calcusuCap();
            await scwin.calcuAccIsuCap();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.edt_PARVAL_OnKillFocus" });
