scwin.img_ISU_ENG_SYMBL_onclick = async function() {
    try {
        if (txb_ISU_ENG_SYMBL.getValue() === "") {
            await $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        } else {
            if ($c.lc.fn_eng_symbl_check(txb_ISU_ENG_SYMBL.getValue())) {
                $c.lc.fn_chkCorpSymblDoubleInput(txb_ISU_ENG_SYMBL.getValue(), txb_ISUR_CD.getValue(), dts_Symbl);
                if (!$c.ut.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                    await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                }
            } else {
                txb_ISU_ENG_SYMBL.focus();
                return false;
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.img_ISU_ENG_SYMBL_onclick" });
    }
};

