/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
            scwin.initForm('C');
        } else {
            scwin.initForm('X');
            let vCurDate = $c.ut.cGetToday("yyyymmdd");
            if (edt_LIST_DD.getValue() > vCurDate) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus(); // disable 시킨다.

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.dts_Isu_OnLoadCompleted" });
    }
};

