/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();
        if (buttonSet.status === "U") {
            let parentWin = $c.frame.path("../");
            parentWin.dts_Isu.setFocusedCell(rowPos, 0);
        }
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92026.trs_Save_OnSuccess" });
    }
};

