 * @returns {void}
 * @hidden N
 */
scwin.cmb_NPARVALSTK_YN_onselchange = function() {
    try {
        if (scwin.vSecugrpID === SECUGRP_ID_DR) {
            return;
        }
        if (cmb_NPARVALSTK_YN.getValue() === "Y") {
            edt_PARVAL.hide();
            edt_PER1STK_CAP.show("");
            edt_PARVAL.setValue("0");
        } else {
            edt_PARVAL.show("");
            edt_PER1STK_CAP.hide();
            edt_PER1STK_CAP.setValue("0");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92026.cmb_NPARVALSTK_YN_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00443 - 통화ISO코드
     */
    const arrCid = [{
        cid: "CURR_ISO_CD",
        cnm: "cmb_CURR_ISO_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
