/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&DIV_IDX=" + DIV_R_LISTING_ST_ISU_DTL;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Newlisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Isu.getCellData(1, "PREFSTK_TP_CD") === '2') {
        chk_PREFSTK_TP_CD.setValue(1);
        scwin.setPREFSTKItem(true);
        scwin.setPanelPREFSTK(true);
    } else {
        scwin.setPREFSTKEvent();
    }
    scwin.setCheckboxData(chk_INDEFINPD_YN, dts_Isu.getCellData(1, "INDEFINPD_YN"));
    scwin.setCheckboxData(chk_PARTCTP_YN, dts_Isu.getCellData(1, "PARTCTP_YN"));
    scwin.setCheckboxData(chk_ACCTP_YN, dts_Isu.getCellData(1, "ACCTP_YN"));
    scwin.setCheckboxData(chk_NDIVTM_VOTERGHT_YN, dts_Isu.getCellData(1, "NDIVTM_VOTERGHT_YN"));
    if (dts_Isu.getCellData(1, "NPARVALSTK_YN") === 'Y') {
        edt_PARVAL.hide();
        edt_PER1STK_CAP.show("");
        edt_PARVAL.setValue("0");
    } else {
        edt_PARVAL.show("");
        edt_PER1STK_CAP.hide();
        edt_PER1STK_CAP.setValue("0");
    }
};

