    //     LD_MKT_TP_CD : js_market,
    //     ISUR_CD : $c.stf.getObjectValue(txb_ISUR_CD) + ",DIV_IDX[0]=" + DIV_IDX_ISS_STK_HIST + ",DIV_IDX[1]=" + DIV_IDX_ISS_PRTDEPO_STK_HIST
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Isu,dts_PRTDEPO",
        target : "trs_Save=body.content",
        isProcessMsg : false
