    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        scwin.visuShrsLabelNm = "DR";
        lb_PARVAL.setValue('DR당액면가/주당자본금');
        lb_BF_ACC_ISU_SHRS.setValue('변경전 상장DR수');
