        lb_ACC_ISU_SHRS.setValue('변경후 상장DR수');

        // showObj(panel_PARVAL, false);
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
            panel_ISU_CAP.hide();
        }
    } else {
        scwin.visuShrsLabelNm = "주식";
        panel_PARVAL.show("");
        panel_ISU_CAP.show("");
    }
    if (scwin.vSecugrpID === SECUGRP_ID_DR || scwin.vSecugrpID === SECUGRP_ID_FS) {
        edt_PARVAL.MaxDecimalPlace = 3;
        edt_ISU_CAP.MaxDecimalPlace = 3;
    } else {
        edt_PARVAL.MaxDecimalPlace = 0;
        edt_ISU_CAP.MaxDecimalPlace = 0;
    }
};

