 * @description get Checkbox Data 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'Y';
    } else {
        return 'N';
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[법인코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_LIST_METHD_TP_CD.getValue() === "") {
        await $c.win.alert("[상장방식]을 선택하세요.");
        cmb_LIST_METHD_TP_CD.focus();
        return false;
    }
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        img_ISU_CD.focus();
        return false;
    }
    if (scwin.TR_JOB === 'I') {
        // 유가일경우에는 푼다.

        // if ( fn_checkDoubleInput(getObjectValue(txb_ISU_CD)) )  return false;

    }

    // if (getObjectValue(cmb_LIST_METHD_TP_CD) == LIST_METHD_TP_CD_1) {
    if (txb_ISU_SRT_CD.getValue() === "") {
        await $c.win.alert("[종목단축코드]항목값이  없습니다."); // txb_ISU_SRT_CD.focus();return false;

    }
    if (txb_ISU_KOR_NM.getValue() === "") {
        await $c.win.alert("[한글종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 60, "한글종목명")) return false;
    if (txb_ISU_KOR_ABBRV.getValue() === "") {
        await $c.win.alert("[한글종목약명]을 입력하세요.");
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 30, "한글종목약명")) return false;
    if (txb_ISU_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문종목명]을 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 60, "영문종목명")) return false;
