/**
 * @method
 * @name calcuAccIsuShrs
 * @description calcu Acc Isu Shrs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuShrs = async function() {
    try {
        let vsum = parseInt(edt_BF_ACC_ISU_SHRS.getValue()) + parseInt(edt_ISU_SHRS.getValue());
        // alert( "[vsum]"+vsum);
        edt_ACC_ISU_SHRS.setValue(vsum);
    } catch (err) {
        await $c.win.alert("[변경후 상장증권수 계산 중 오류]" + err);
    }
};

/**
 * @method
 * @name calcusuCap
 * @description calcusu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcusuCap = async function() {
    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        edt_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = cmb_STK_ISU_RSN_CD.getValue();
            let vsum = 0;
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 약면변합
                vRsnCd === '171') {
                // 액면분할
                vsum = 0; // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 약면변합
                vRsnCd === '641') {
                // 액면분할
                vsum = 0; // 코스닥

            } else {
                if (scwin.vSecugrpID === SECUGRP_ID_MF || scwin.vSecugrpID === SECUGRP_ID_IF) {
                    vsum = parseFloat(edt_ISU_PRC.getValue()) * parseFloat(edt_ISU_SHRS.getValue());
                } else {
                    vsum = parseFloat(edt_PARVAL.getValue()) * parseFloat(edt_ISU_SHRS.getValue());
                }
            }
            // alert( "[증감자본금 vsum]"+vsum);
            edt_ISU_CAP.setValue(vsum);
        } catch (err) {
            await $c.win.alert("[증감 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name calcuAccIsuCap
 * @description calcu Acc Isu Cap 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcuAccIsuCap = async function() {
    if (scwin.vSecugrpID === SECUGRP_ID_DR) {
        edt_ACC_ISU_CAP.setValue('');
    } else {
        try {
            let vRsnCd = cmb_STK_ISU_RSN_CD.getValue();
            let vsum = '';
            if (vRsnCd === '118' || // 이익소각
                vRsnCd === '160' || // 상호변경
                vRsnCd === '170' || // 약면변합
                vRsnCd === '171') {
                // 액면분할
                vsum = edt_BF_ACC_ISU_CAP.getValue(); // 유가
                edt_ISU_CAP.setValue(0); // 유가

            } else if (vRsnCd === '626' || // 이익소각
                vRsnCd === '643' || // 상호변경
                vRsnCd === '640' || // 약면변합
                vRsnCd === '641') {
                // 액면분할
                vsum = edt_BF_ACC_ISU_CAP.getValue(); // 코스닥
                edt_ISU_CAP.setValue(0); // 코스닥

            } else {
                await scwin.calcusuCap();
                vsum = parseFloat(edt_BF_ACC_ISU_CAP.getValue()) + parseFloat(edt_ISU_CAP.getValue());
            }
            edt_ACC_ISU_CAP.setValue(vsum);
        } catch (err) {
            await $c.win.alert("[변경후 상장자본금 계산 중  오류]" + err);
        }
    }
};

/**
 * @method
 * @name openDetailPrtdepo
 * @description 보호예수신규등록시
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailPrtdepo = async function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.gPrtdepoSeq = row;
    } else {
        // 신규버튼 선택시
        scwin.gPrtdepoSeq = ""; // 초기화

    }
    const options = {
        id: "ULDSTF92025",
        title: "의무보유 등록/수정",
        type: "browserPopup",
        width: "800px",
        height: "320px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92025.gfm", options);
};
